# epochs round trip
ep = mne.Epochs(raw, ev, {"a": 1, "b": 2, "c/x": 3}, tmin=-0.1, tmax=0.3,
                reject={"eeg": 2e-4}, preload=True)
check("ep_n", [len(ep)])
