checks("epo_ids", [k + "=" + str(v) for k, v in e2.event_id.items()])

# evoked round trip
ea = ep["a"].average()
eb = ep["b"].average()
mne.write_evokeds("build/t-ave.fif", [ea, eb], overwrite=True)
